from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1]
base='https://abide-labs.com'
nav_items=[('/projects/','Projects'),('/capabilities/','Capabilities'),('/#about','About'),('/contact/','Get in touch')]
def header(active):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==url else '')+(' class="nav-contact"' if url=='/contact/' else '')+f'>{label}</a>' for url,label in nav_items)
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="container nav-wrap"><a class="brand" href="/" aria-label="Abide Labs home"><img src="/assets/brand/wordmark.webp" width="440" height="59" alt="Abide"><small>LABS</small></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="primary-nav">Menu</button><nav class="nav-links" id="primary-nav" aria-label="Main navigation">{links}</nav></div></header>'''
def footer():
 return '''<footer class="site-footer"><div class="container"><div class="footer-top"><a class="brand" href="/" aria-label="Abide Labs home"><img src="/assets/brand/wordmark.webp" width="440" height="59" alt="Abide"><small>LABS</small></a><div class="footer-links"><a href="/projects/">Projects</a><a href="/capabilities/">Capabilities</a><a href="/contact/">Contact</a><a href="https://www.linkedin.com/company/abide-labs/">LinkedIn</a></div></div><div class="footer-bottom"><span>© 2026 Abide Labs. Independent product development.</span><div class="footer-links"><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a><a href="/support.html">Product support</a></div></div></div></footer>'''
def band():
 return '''<section class="contact-band" aria-labelledby="collaboration-heading"><div class="container"><div><p class="eyebrow">Work with Abide Labs</p><h2 id="collaboration-heading">Have a problem worth building for?</h2><p>Tell us what people need to do and where the current process breaks.</p></div><a class="button" href="/contact/">Discuss a project <span class="arrow" aria-hidden="true">↗</span></a></div></section>'''
def page(path,title,description,body,active='',crumbs=None):
 url=base+path
 graph=[{'@type':'Organization','@id':base+'/#organization','name':'Abide Labs','url':base+'/','email':'hello@abide-labs.com','logo':base+'/logo-icon.png','description':'Independent development of AI-powered products, workflow systems, and creative production tools.'},{'@type':'WebSite','@id':base+'/#website','name':'Abide Labs','url':base+'/','publisher':{'@id':base+'/#organization'}},{'@type':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':description,'isPartOf':{'@id':base+'/#website'},'about':{'@id':base+'/#organization'}}]
 if crumbs:
  graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':base+p} for i,(p,n) in enumerate(crumbs)]})
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}"><meta name="robots" content="noindex,follow"><meta name="theme-color" content="#0F1B2D"><link rel="canonical" href="{url}"><link rel="icon" href="/assets/brand/mark.webp" type="image/webp"><meta property="og:type" content="website"><meta property="og:site_name" content="Abide Labs"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{base}/assets/social-share.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Abide Labs. AI products and systems, built with purpose."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title,quote=True)}"><meta name="twitter:description" content="{escape(description,quote=True)}"><meta name="twitter:image" content="{base}/assets/social-share.jpg"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},separators=(',',':'))}</script></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
 dest=root/('index.html' if path=='/' else path.strip('/')+'/index.html')
 dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc.replace('><','>\n<')+'\n')
def crumb(items):
 return '<nav class="breadcrumb" aria-label="Breadcrumb">'+'<span aria-hidden="true">/</span>'.join(f'<a href="{p}">{n}</a>' if i<len(items)-1 else f'<span aria-current="page">{n}</span>' for i,(p,n) in enumerate(items))+'</nav>'
def diagram(kind):
 if kind=='bellringer':
  return '''<figure class="project-visual" aria-label="BellRinger intended workflow"><div class="diagram-heading">BellRinger / Workflow under development</div><ol class="flow"><li><span>01</span>Sales inquiry</li><li><span>02</span>Capture context</li><li><span>03</span>Approved next step</li><li><span>04</span>Staff handoff</li></ol><figcaption class="diagram-caption">Intended workflow. Pilot readiness is evaluated separately.</figcaption></figure>'''
 return '''<figure class="project-visual" aria-label="Video Studio supervised production workflow"><div class="diagram-heading">AI Video Studio / Supervised production</div><div class="studio-flow"><div><small>01</small>Script &amp; narration</div><div><small>02</small>Presenter &amp; B-roll</div><div><small>03</small>Timeline &amp; captions</div><div><small>04</small>Review &amp; export</div></div><figcaption class="diagram-caption">A workflow map, with human review before final approval.</figcaption></figure>'''
def features():
 return f'''<article class="project-feature">{diagram('bellringer')}<div class="project-copy"><div class="project-meta"><span>Voice workflows</span><span>In development</span></div><h3>BellRinger</h3><p>A dealership voice system being developed around sales inquiries, lead information, and clear handoffs to dealership staff. The current focus is preparation for a controlled pilot.</p><a class="text-link" href="/projects/bellringer/">Explore BellRinger <span aria-hidden="true">↗</span></a></div></article><article class="project-feature reverse">{diagram('studio')}<div class="project-copy"><div class="project-meta"><span>Creative production</span><span>Internal working tools</span></div><h3>AI Video Studio</h3><p>Tools for organizing scripts, narration, fictional presenters, B-roll, captions, and video assembly. Development focuses on a supervised workflow that keeps revisions and review decisions connected.</p><a class="text-link" href="/projects/video-studio/">Inside the production workflow <span aria-hidden="true">↗</span></a></div></article>'''
def smaller():
 return '''<div class="project-index"><article id="readerrealms"><div class="project-meta"><span>Interactive storytelling</span><span>Prototype in development</span></div><h3>ReaderRealms</h3><p>An iPhone-first storytelling project exploring how readers can move through authored fictional spaces. The current Unity work is a contained vertical slice, with exploration and cinematic composition at its center.</p></article><article id="gumbo"><div class="project-meta"><span>Veterinary care discovery</span><span>Local research prototype</span></div><h3>Gumbo</h3><p>A prototype for comparing veterinary capabilities and source-linked price information. The current research sample is limited. Listings are not clinic-verified, and the tool does not provide medical triage or appointment booking.</p></article></div>'''
home='''<section class="hero" aria-labelledby="hero-title"><div class="hero-media" aria-hidden="true"><img src="/assets/hero-poster.webp" alt="" width="960" height="960" fetchpriority="high"><video id="brand-film" muted loop playsinline preload="none" aria-hidden="true" tabindex="-1"></video></div><div class="hero-shade"></div><div class="container hero-content"><p class="eyebrow">Abide Labs / Independent AI product development</p><h1 id="hero-title">AI products and systems,<em>built with purpose.</em></h1><p class="hero-copy">We develop AI-powered software for business workflows and creative production, alongside experiments in how people explore stories and find useful information.</p><div class="actions"><a class="button" href="/projects/">Explore our work <span class="arrow" aria-hidden="true">↗</span></a><a class="text-link" href="/contact/">Discuss a project</a></div></div><div class="container hero-bottom"><span class="hero-note">From focused prototypes<br>to systems people can use.</span><button hidden id="motion-toggle" class="motion-button" type="button" aria-pressed="false" aria-controls="brand-film">Play background video</button></div></section><section class="intro-strip"><div class="container intro-inner"><p class="eyebrow">A product-led practice</p><p>Useful software starts with understanding the work. Our own products give us a place to test ideas, examine limitations, and carry what we learn into the next build.</p></div></section>'''
home+='''<section class="section" id="projects"><div class="container"><div class="section-head"><div><p class="eyebrow">Selected work</p><h2>A closer look<br>at our work.</h2></div><p>Projects at different stages, with a clear account of what each one is being built to do.</p></div>'''+features()+'''<div class="actions"><a class="text-link" href="/projects/">View the project portfolio <span aria-hidden="true">↗</span></a></div></div></section>'''
home+='''<section class="section paper" id="workflows"><span id="workflow-examples" class="legacy-anchor"></span><div class="container cap-layout"><div class="cap-intro"><p class="eyebrow">Capabilities</p><h2>The engineering<br>behind useful AI.</h2><p>Models are one part of a working product. The surrounding software determines what it can do, how it recovers, and when a person needs to step in.</p><a class="text-link" href="/capabilities/">How we build <span aria-hidden="true">↗</span></a></div><div class="cap-list"><div class="cap-row"><h3>AI applications &amp; workflow automation</h3><p>Product interfaces, structured information, and defined next steps for work such as intake, follow-up, and content preparation.</p></div><div class="cap-row"><h3>Agent coordination &amp; human review</h3><p>Bounded tasks, recorded handoffs, and explicit review points. We distinguish a requested action from a verified result.</p></div><div class="cap-row"><h3>Generative media production</h3><p>Audio, images, and video connected through versioned assets, editorial tools, and supervised production workflows.</p></div></div></div></section>'''
home+='''<section class="section" id="about"><div class="container principles"><div><p class="eyebrow">About Abide Labs</p><h2>Engineering informed<br>by the work.</h2><p>Abide Labs is an independent technology company developing its own products and exploring practical applications of AI. Our work connects software engineering with the details of how people actually use a system.</p><p>We are building toward more useful AI applications and more dependable ways to coordinate them. That means testing a small, meaningful use case before expanding its scope.</p></div><ol class="principle-list"><li><span>01</span><div>Understand the work before changing it.</div></li><li><span>02</span><div>Build the smallest useful system.</div></li><li><span>03</span><div>Keep people in control of consequential decisions.</div></li><li><span>04</span><div>Only claim what the evidence supports.</div></li></ol></div></section>'''+band()
page('/','Abide Labs | AI Product Development & Workflow Systems','Abide Labs develops AI-powered products, workflow systems, and creative production tools. Explore BellRinger, AI Video Studio, and projects in development.',home)
projects='''<section class="page-hero"><div class="container"><p class="eyebrow">Project portfolio</p><h1>What we’re building.</h1><p>Business workflows, creative production, and new product ideas. Each project has its own proof to earn.</p><p class="status-line">Development status reviewed November 2026.</p></div></section><section class="section"><div class="container">'''+features()+smaller()+'''<p class="work-note">These projects are not presented as generally available commercial products. BellRinger is in development for a controlled pilot. AI Video Studio is internal tooling. ReaderRealms and Gumbo remain prototypes. For current access or collaboration inquiries, <a href="/contact/">contact Abide Labs</a>.</p></div></section>'''+band()
page('/projects/','AI Products & Projects | Abide Labs','Explore BellRinger, AI Video Studio, ReaderRealms, and Gumbo, with explicit development status and factual descriptions of each project.',projects,'/projects/',[('/','Home'),('/projects/','Projects')])
cap='''<section class="page-hero"><div class="container"><p class="eyebrow">Capabilities &amp; applied research</p><h1>Make the model part<br>of a working system.</h1><p>Our projects combine AI with product interfaces, workflow logic, media tools, and review. We start with a specific task and test the parts around the model as carefully as the model itself.</p></div></section><section class="section"><div class="container case-layout"><aside class="case-aside"><p class="eyebrow">Areas of work</p><p>Product development<br>Workflow automation<br>Creative tools<br>Agent coordination</p></aside><div class="article"><h2>AI-powered applications</h2><p>We develop the software around an AI interaction: the interface, the data it needs, the permitted next steps, and the record of what happened. BellRinger applies this approach to dealership voice workflows under development.</p><p>Relevant work: <a href="/projects/bellringer/">BellRinger project overview</a>.</p><h2>Business workflow automation</h2><p>Intake, follow-up, scheduling, and internal administration are useful starting points when their inputs and responsibilities are clear. We examine the existing process, define where software can help, and identify decisions that should stay with people.</p><p>Integration readiness is specific to each project. We do not treat a local test as evidence that a live customer system is connected.</p><h2>Generative AI production systems</h2><p>Our video work connects narration, fictional presenters, B-roll, captions, and timeline editing. The development challenge is keeping the script, selected assets, revisions, and review decisions consistent through an export.</p><p>Relevant work: <a href="/projects/video-studio/">AI Video Studio workflow</a>.</p><h2>Multi-agent orchestration &amp; governance</h2><p>Our development tooling explores how to assign bounded tasks, carry context through handoffs, and record evidence before treating work as complete. Human approval and limits on an agent’s authority are part of that operating approach.</p><p>This is an internal engineering practice and an area of continued experimentation. It is not offered here as a standalone commercial orchestration platform.</p><h2>Product experiments</h2><p>ReaderRealms explores authored interactive storytelling. Gumbo examines evidence-linked veterinary care discovery. Both help us investigate product questions in a limited prototype before making broader promises.</p><p><a href="/projects/#readerrealms">ReaderRealms</a> · <a href="/projects/#gumbo">Gumbo</a></p><h2>Discussing a possible build</h2><p>We welcome conversations with business operators, product teams, and creative collaborators who can describe a concrete need. The first question is what a useful result would look like and how we could verify it.</p><a class="text-link" href="/contact/">Tell us about the work <span aria-hidden="true">↗</span></a></div></div></section>'''
page('/capabilities/','AI Applications, Agent Systems & Automation | Abide Labs','AI application development, business workflow automation, supervised media production, and internal research into multi-agent coordination.',cap,'/capabilities/',[('/','Home'),('/capabilities/','Capabilities')])
for slug,name,desc,intro,status,focus,content in [
 ('bellringer','BellRinger','A dealership voice workflow system in development for a controlled pilot. Learn about the intended workflow and current limits.','Voice workflows for dealership sales inquiries.','In development for a controlled pilot','Sales intake and staff handoff','''<h2>The problem</h2><p>A dealership inquiry can involve vehicle questions, contact information, appointment preferences, and a request for staff help. The next action needs a clear owner, and the record needs to match what actually happened.</p><h2>What is being developed</h2><p>BellRinger is being built around a bounded set of dealership sales voice workflows. The intended system captures relevant context, follows an approved disposition, and supports a clear handoff to dealership staff.</p>'''+diagram('bellringer')+'''<h2>The engineering focus</h2><p>The development work separates the conversation from the rules governing its next action. A local record, a requested external action, and a verified result are treated as distinct states.</p><p>Workflow-specific review and activation decisions remain necessary before live use. Intended appointment and follow-up behavior should not be read as a claim of a currently activated dealership service.</p><h2>Current status</h2><p>BellRinger is in development for a controlled pilot. This page does not claim a completed paid pilot, general commercial availability, or any particular live CRM integration.</p><div class="note">For product inquiries or a conversation about the pilot’s current readiness, <a href="/contact/?topic=BellRinger">contact Abide Labs about BellRinger</a>.</div>'''),
 ('video-studio','AI Video Studio','Internal tools for supervised AI video production, connecting scripts, narration, presenter assets, B-roll, captions, editing, and review.','A supervised workflow for AI video production.','Internal working tools; continued development','Script-to-export production workflow','''<h2>The problem</h2><p>A video project can spread across scripts, audio files, generated takes, captions, and editing tools. A revision to one part can leave the others out of sync. Production needs a way to preserve earlier work and identify the version ready for review.</p><h2>What has been built</h2><p>Our internal video tooling organizes scripts, narration, presenter references, B-roll, timelines, and exports. It supports review records and versioned assets so editorial decisions can stay connected to the production work.</p>'''+diagram('studio')+'''<h2>How the work is supervised</h2><p>Generation and editorial assembly have separate checks. A completed render is a candidate for review. Approving a take or narration does not automatically approve the final video.</p><p>Development also examines resumable production, asset reuse, and explicit spending limits for paid generation. Provider and workflow readiness vary; those controls do not imply every generation step is fully automated.</p><h2>Current status</h2><p>AI Video Studio describes internal working production tools and ongoing integration work. It is not a publicly available software subscription. Unattended end-to-end production is not claimed.</p><div class="note">We can discuss the workflow without publishing client media, presenter libraries, or private production records. <a href="/contact/?topic=Video%20production">Ask about the production approach</a>.</div>''')]:
 path='/projects/'+slug+'/'
 items=[('/','Home'),('/projects/','Projects'),(path,name)]
 body=f'''<section class="page-hero"><div class="container">{crumb(items)}<p class="eyebrow">Project notes / {escape(name)}</p><h1>{intro}</h1><p class="status-line">{status}</p></div></section><section class="section"><div class="container case-layout"><aside class="case-aside"><dl><div><dt>Project</dt><dd>{name}</dd></div><div><dt>Status</dt><dd>{status}</dd></div><div><dt>Focus</dt><dd>{focus}</dd></div></dl><a href="/projects/" class="text-link">All projects</a></aside><div class="article">{content}</div></div></section>'''+band()
 page(path,name+' | Abide Labs Project Notes',desc,body,'/projects/',items)
contact='''<section class="page-hero"><div class="container"><p class="eyebrow">Contact &amp; collaboration</p><h1>Let’s talk about the work.</h1><p>Bring a workflow that needs attention, a product question, or a collaboration idea. A clear description of the problem is a useful place to start.</p></div></section><section class="section"><div class="container contact-layout"><div class="contact-details"><p class="eyebrow">A direct conversation</p><a class="contact-email" href="mailto:hello@abide-labs.com">hello@abide-labs.com</a><p style="margin-top:24px">Tell us who the work is for, what you need to improve, and what you have already tried. For a product inquiry, include the project name.</p><p class="small">Please leave out passwords, confidential customer records, and other sensitive information.</p><a class="text-link" href="/projects/">Explore our current projects</a></div><form class="inquiry-form" id="inquiry-form" action="mailto:hello@abide-labs.com" method="post" enctype="text/plain"><h2 style="font-size:1.6rem">Prepare an inquiry</h2><p class="small">This form prepares a draft in your email app. It does not send a message or store your details on this website.</p><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="120"></div><div class="field"><label for="email">Your email</label><input type="email" id="email" name="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="topic">What would you like to discuss?</label><select id="topic" name="topic"><option>Project collaboration</option><option>Workflow automation</option><option>BellRinger</option><option>Video production</option><option>ReaderRealms</option><option>Gumbo</option><option>Other inquiry</option></select></div><div class="field"><label for="message">Tell us about the work</label><textarea id="message" name="message" required maxlength="3000"></textarea></div><div class="contact-form-actions"><button class="button" type="submit">Open email draft <span aria-hidden="true">↗</span></button><button class="copy-button" type="button" id="copy-inquiry">Copy inquiry</button></div><p class="form-note">Review and send the message from your email app. You can also email us directly.</p><p id="draft-status" class="copy-status" role="status" aria-live="polite"></p><noscript><p>Email <a href="mailto:hello@abide-labs.com">hello@abide-labs.com</a> directly. Preparing a draft with this form requires JavaScript.</p></noscript></form></div></section>'''
page('/contact/','Contact Abide Labs | Projects & Collaboration','Contact Abide Labs about AI products, workflow automation, video production, or a possible collaboration. Email hello@abide-labs.com.',contact,'/contact/',[('/','Home'),('/contact/','Contact')])
page('/404/','Page Not Found | Abide Labs','Return to Abide Labs to explore current projects and capabilities.','<section class="section not-found"><div class="container"><p class="eyebrow">404 / Page not found</p><h1>This page has moved<br>or does not exist.</h1><p>Explore our current projects or get in touch.</p><div class="actions"><a class="button" href="/">Return home</a><a class="text-link" href="/projects/">View projects</a></div></div></section>')
