audit='''<section class="page-hero"><div class="container"><p class="eyebrow">Workflow inquiry</p><h1>Start with one workflow.</h1><p>Request a 15-minute conversation about a repetitive process in your business and where a focused software build might help.</p></div></section><section class="section"><div class="container article"><h2>What to bring</h2><p>Describe how the work begins, who handles it, and where information or follow-up gets lost. Examples include incoming inquiries, customer intake, appointment coordination, and internal administration.</p><h2>What we can discuss</h2><p>We can examine the current process, identify where AI might be useful, and discuss what a small first build would need to prove. Scope, availability, and any implementation terms are agreed separately.</p><div class="actions"><a class="button" href="mailto:hello@abide-labs.com?subject=Workflow%20review%20inquiry">Request a workflow conversation <span aria-hidden="true">↗</span></a><a class="text-link" href="/contact/">Prepare an inquiry</a></div><p class="small" style="margin-top:24px">These links open an email draft or our inquiry page. They do not book an appointment.</p></div></section>'''
page('/audit/','AI Workflow Review | Abide Labs','Discuss one business workflow with Abide Labs, including inquiry handling, intake, appointment coordination, or repetitive administration.',audit,'/contact/',[('/','Home'),('/audit/','Workflow review')])
support='''<section class="page-hero"><div class="container"><p class="eyebrow">Product support</p><h1>Help with an Abide Labs product.</h1><p>Email the product name, what you were trying to do, and the issue you encountered. Please omit passwords and confidential information.</p></div></section><section class="section"><div class="container article"><a class="contact-email" href="mailto:hello@abide-labs.com?subject=Product%20support">hello@abide-labs.com</a><h2>Existing product documentation</h2><p>These links preserve access to published support and policy documents. Their presence does not establish current product availability.</p><ul><li>Nuhra: <a href="/nuhra-support.html">Support</a>, <a href="/nuhra-privacy.html">Privacy</a>, <a href="/nuhra-terms.html">Terms</a></li><li>Think2x: <a href="/think2x-privacy.html">Privacy</a>, <a href="/think2x-terms.html">Terms</a></li><li>BellRinger: <a href="/bellringer-privacy.html">Privacy</a>, <a href="/bellringer-terms.html">Terms</a></li></ul><h2>Purchases and subscriptions</h2><p>Include the product name and purchase platform in your inquiry. Do not email payment-card details.</p><h2>Current development</h2><p>See the <a href="/projects/">project portfolio</a> for development-stage descriptions. For other products previously associated with Abide Labs, ask us about their current status.</p></div></section>'''
page('/support/','Product Support | Abide Labs','Contact Abide Labs for product support and access existing Nuhra, Think2x, and BellRinger policy documents.',support,'',[('/','Home'),('/support.html','Product support')])
(root/'support.html').write_text((root/'support/index.html').read_text().replace(base+'/support/',base+'/support.html'))
(root/'support/index.html').unlink();(root/'support').rmdir()
